# Let me find all rectangular bounding boxes that contain multiple colors 
# and check if any have consistent completion rules

import numpy as np

def get_filled_rects(grid):
    """Find all maximal filled rectangles of uniform color"""
    h, w = grid.shape
    # For each pixel, expand as far as possible in horizontal direction
    rects = []

    for r in range(h):
        row_vals = grid[r]
        i = 0
        while i < w:
            j = i + 1
            while j < w and row_vals[j] == row_vals[i]:
                j += 1
            length = j - i
            if length >= 2:
                rects.append((r, i, j))  # (row, start_col, end_col)
            i = j

    return rects

# Look for potential rectangular completions
print("=== Looking for near-complete rectangles ===")
for color in [3, 5, 9]:
    mask = (grid == color)

    # Find all rectangular bounding boxes that are >50% filled
    found_boxes = []
    for r_start in range(h := grid.shape[0]):
        for c_start in range(w := grid.shape[1]):
            if not mask[r_start, c_start]:
                continue

            # Expand to find bounds
            max_r, max_c = r_start, c_start
            for r in range(r_start, h):
                for c in range(c_start, w):
                    if mask[r, c]:
                        max_r, max_c = max(max_r, r), max(max_c, c)

            bbox_area = (max_r - r_start + 1) * (max_c - c_start + 1)
            actual_pixels = np.sum(mask[r_start:max_r+1, c_start:max_c+1])

            if bbox_area > 4 and actual_pixels >= bbox_area * 0.7:
                hole_mask = ~mask[r_start:max_r+1, c_start:max_c+1]
                holes = np.argwhere(hole_mask)
                found_boxes.append({
                    'color': color,
                    'bbox': (r_start, c_start, max_r, max_c),
                    'area': bbox_area,
                    'actual': actual_pixels,
                    'holes': list(holes)
                })

    print(f"\nColor {color} near-complete boxes:")
    for box in sorted(found_boxes, key=lambda x: x['area'], reverse=True)[:10]:
        print(f"  bbox={box['bbox']}, area={box['area']}, filled={box['actual']}/{box['area']}, holes={box['holes']}")

# Finalize the submission - fill 9-region to be complete 7x3 rectangle
output = grid.tolist()

# Fill in rows 19-24, cols 22-23 with 9s
for r in range(19, 25):
    for c in range(22, 24):
        output[r][c] = 9

print("Submitting first guess:")
for r in range(23, 26):
    print(f"Row {r}: {[output[r][c] for c in range(20, 24)]}")

# Fix: create new grid instead of mutating list of lists
output = [row[:] for row in grid]  # Deep copy

# Fill in rows 19-24, cols 22-23 with 9s
for r in range(19, 25):
    for c in range(22, 24):
        output[r][c] = 9

print("Submitting first guess:")
print(f"Shape: {len(output)}x{len(output[0])}")
print(f"Modified cells at (r,c) -> value:")
for r in range(19, 25):
    for c in range(22, 24):
        print(f"  ({r},{c}): 9")

